function solve(num1, num2) {
  function addStrings(a, b) {
    var i = a.length - 1;
    var j = b.length - 1;
    var carry = 0;
    var digits = [];
    while (i >= 0 || j >= 0 || carry > 0) {
      var sum = carry;
      if (i >= 0) {
        sum += a.charCodeAt(i) - 48;
        i--;
      }
      if (j >= 0) {
        sum += b.charCodeAt(j) - 48;
        j--;
      }
      digits.push(String(sum % 10));
      carry = Math.floor(sum / 10);
    }
    return digits.reverse().join('');
  }

  function multiplyByDigit(num, digit) {
    if (digit === 0) return '0';
    var digits = [];
    var carry = 0;
    var k = num.length - 1;
    while (k >= 0) {
      var product = (num.charCodeAt(k) - 48) * digit + carry;
      digits.push(String(product % 10));
      carry = Math.floor(product / 10);
      k--;
    }
    if (carry > 0) digits.push(String(carry));
    return digits.reverse().join('');
  }

  var m = num2.length;
  var total = '0';
  for (var j = 0; j < m; j++) {
    var digit = num2.charCodeAt(j) - 48;
    if (digit === 0) continue;
    var row = multiplyByDigit(num1, digit) + '0'.repeat(m - 1 - j);
    total = addStrings(total, row);
  }
  var trimmed = total.replace(/^0+/, '');
  return trimmed === '' ? '0' : trimmed;
}

function solve(num1, num2) {
  var n = num1.length;
  var m = num2.length;
  var digits = new Array(n + m);
  for (var q = 0; q < n + m; q++) digits[q] = 0;
  for (var i = n - 1; i >= 0; i--) {
    var a = num1.charCodeAt(i) - 48;
    for (var j = m - 1; j >= 0; j--) {
      var b = num2.charCodeAt(j) - 48;
      var product = a * b + digits[i + j + 1];
      digits[i + j + 1] = product % 10;
      digits[i + j] += Math.floor(product / 10);
    }
  }
  var out = digits.join('').replace(/^0+/, '');
  return out === '' ? '0' : out;
}
